    public function parse_ws_ticker(array $ticker, ?array $market = null) {
        //
        //    {
        //        "symbol" : "BTC_KRW",           // 통화코드
        //        "tickType" : "24H",                 // 변동 기준시간- 30M, 1H, 12H, 24H, MID
        //        "date" : "20200129",                // 일자
        //        "time" : "121844",                  // 시간
        //        "openPrice" : "2302",               // 시가
        //        "closePrice" : "2317",              // 종가
        //        "lowPrice" : "2272",                // 저가
        //        "highPrice" : "2344",               // 고가
        //        "value" : "2831915078.07065789",    // 누적거래금액
        //        "volume" : "1222314.51355788",  // 누적거래량
        //        "sellVolume" : "760129.34079004",   // 매도누적거래량
        //        "buyVolume" : "462185.17276784",    // 매수누적거래량
        //        "prevClosePrice" : "2326",          // 전일종가
        //        "chgRate" : "0.65",                 // 변동률
        //        "chgAmt" : "15",                    // 변동금액
        //        "volumePower" : "60.80"         // 체결강도
        //    }
        //
        // generation 2
        //
        //     {
        //         "type" => "ticker",
        //         "code" => "KRW-BTC",
        //         "opening_price" => 94223000,
        //         "high_price" => 95465000,
        //         "low_price" => 93601000,
        //         "trade_price" => 95299000,
        //         "prev_closing_price" => 94201000,
        //         "change" => "RISE",
        //         "change_price" => 1098000,
        //         "signed_change_price" => 1098000,
        //         "change_rate" => 0.01165593,
        //         "signed_change_rate" => 0.01165593,
        //         "trade_volume" => 0.0094,
        //         "acc_trade_volume" => 151.44914647,
        //         "acc_trade_volume_24h" => 310.44065227,
        //         "acc_trade_price" => 14330306973.41015,
        //         "acc_trade_price_24h" => 29226371799.56915,
        //         "trade_date" => "20260710",
        //         "trade_time" => "124548",
        //         "trade_timestamp" => 1783655148303,
        //         "ask_bid" => "BID",
        //         "acc_ask_volume" => 52.30413928,
        //         "acc_bid_volume" => 99.14500719,
        //         "highest_52_week_price" => 179734000,
        //         "highest_52_week_date" => "2025-10-09",
        //         "lowest_52_week_price" => 81110000,
        //         "lowest_52_week_date" => "2026-02-06",
        //         "market_state" => "ACTIVE",
        //         "is_trading_suspended" => false,
        //         "delisting_date" => "",
        //         "market_warning" => "NONE",
        //         "timestamp" => 1783655148485,
        //         "stream_type" => "REALTIME"
        //     }
        //
        $code = $this->safe_string($ticker, 'code');
        if ($code !== null) {
            $ticker['market'] = $this->safe_string($ticker, 'market', $code);
            return $this->parse_ticker($ticker, $market);
        }
        $date = $this->safe_string($ticker, 'date', '');
        $time = $this->safe_string($ticker, 'time', '');
        $kstDatetime = mb_substr($date, 0, 4 - 0) . '-' . mb_substr($date, 4, 6 - 4) . '-' . mb_substr($date, 6, 8 - 6) . 'T' . mb_substr($time, 0, 2 - 0) . ':' . mb_substr($time, 2, 4 - 2) . ':' . mb_substr($time, 4, 6 - 4);
        // date/time are the exchange's local KST wall-clock, not UTC — shift -9h like parseWsTrade
        $timestamp = $this->parse8601($kstDatetime);
        if ($timestamp !== null) {
            $timestamp = ($timestamp - 32400000);
        }
        $marketId = $this->safe_string($ticker, 'symbol');
        return $this->safe_ticker(array(
            'symbol' => $this->safe_symbol($marketId, $market, '_'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => $this->safe_string($ticker, 'highPrice'),
            'low' => $this->safe_string($ticker, 'lowPrice'),
            'bid' => null,
            'bidVolume' => $this->safe_string($ticker, 'buyVolume'),
            'ask' => null,
            'askVolume' => $this->safe_string($ticker, 'sellVolume'),
            'vwap' => null,
            'open' => $this->safe_string($ticker, 'openPrice'),
            'close' => $this->safe_string($ticker, 'closePrice'),
            'last' => null,
            'previousClose' => $this->safe_string($ticker, 'prevClosePrice'),
            'change' => $this->safe_string($ticker, 'chgAmt'),
            'percentage' => $this->safe_string($ticker, 'chgRate'),
            'average' => null,
            'baseVolume' => $this->safe_string($ticker, 'volume'),
            'quoteVolume' => $this->safe_string($ticker, 'value'),
            'info' => $ticker,
        ), $market);
    }

