    public function parse_ws_order(mixed $order, ?array $market = null) {
        //
        //    {
        //        "type" => "myOrder",
        //        "code" => "KRW-BTC",
        //        "uuid" => "C0101000000001818113",
        //        "ask_bid" => "BID",
        //        "order_type" => "limit",
        //        "state" => "trade",
        //        "trade_uuid" => "C0101000000001744207",
        //        "price" => 1927000,
        //        "volume" => 0.4697,
        //        "remaining_volume" => 0.0803,
        //        "executed_volume" => 0.4697,
        //        "trades_count" => 1,
        //        "reserved_fee" => 0,
        //        "remaining_fee" => 0,
        //        "paid_fee" => 0,
        //        "executed_funds" => 905111.9000,
        //        "trade_timestamp" => 1727052318148,
        //        "order_timestamp" => 1727052318074,
        //        "timestamp" => 1727052318369,
        //        "stream_type" => "REALTIME"
        //    }
        //
        $marketId = $this->safe_string($order, 'code');
        $symbol = $this->safe_symbol($marketId, $market, '-');
        $timestamp = $this->safe_integer($order, 'order_timestamp');
        $sideId = $this->safe_string($order, 'ask_bid');
        $side = $this->safe_string_lower($order, 'side');
        if ($sideId !== null) {
            $side = ($sideId === 'BID') ? ('buy') : ('sell');
        }
        $typeId = $this->safe_string($order, 'order_type');
        $type = null;
        if ($typeId === 'limit') {
            $type = 'limit';
        } elseif ($typeId === 'price') {
            $type = 'market';
        } elseif ($typeId === 'market') {
            $type = 'market';
        }
        $stateId = $this->safe_string($order, 'state');
        $status = null;
        if ($stateId === 'wait') {
            $status = 'open';
        } elseif ($stateId === 'trade') {
            $status = 'open';
        } elseif ($stateId === 'done') {
            $status = 'closed';
        } elseif ($stateId === 'cancel') {
            $status = 'canceled';
        }
        $price = $this->safe_string_2($order, 'price', 'order_price');
        $amount = $this->safe_string_2($order, 'volume', 'order_quantity');
        $remaining = $this->safe_string($order, 'remaining_volume');
        $filled = $this->safe_string($order, 'executed_volume');
        $cost = $this->safe_string($order, 'executed_funds');
        $feeCost = $this->safe_string($order, 'paid_fee');
        $fee = null;
        if ($feeCost !== null) {
            $marketForFee = $this->safe_market($marketId, $market);
            $feeCurrency = $this->safe_string($marketForFee, 'quote');
            $fee = array(
                'cost' => $feeCost,
                'currency' => $feeCurrency,
            );
        }
        return $this->safe_order(array(
            'info' => $order,
            'id' => $this->safe_string_2($order, 'uuid', 'order_id'),
            'clientOrderId' => null,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => $this->safe_integer($order, 'trade_timestamp'),
            'symbol' => $symbol,
            'type' => $type,
            'timeInForce' => null,
            'postOnly' => null,
            'side' => $side,
            'price' => $price,
            'stopPrice' => null,
            'triggerPrice' => null,
            'amount' => $amount,
            'cost' => $cost,
            'average' => null,
            'filled' => $filled,
            'remaining' => $remaining,
            'status' => $status,
            'fee' => $fee,
            'trades' => null,
        ), $market);
    }

    public function handle_message(Client $client, mixed $message) {
        if (gettype($message) === 'string') {
            $content = strtolower($message);
            if ($content === 'pong') {
                $this->handle_pong($client, $message);
                return;
            }
            if ($content === 'ping') {
                $this->handle_ping($client, $message);
                return;
            }
            return;
        }
        $status = $this->safe_string($message, 'status');
        if ($status === 'UP') {
            $this->handle_pong($client, $message);
            return;
        }
        if ((is_array($message) && array_key_exists('pong' ?? '', $message)) || (is_array($message) && array_key_exists('PINGPONG' ?? '', $message))) {
            $this->handle_pong($client, $message);
            return;
        }
        if (is_array($message) && array_key_exists('ping' ?? '', $message)) {
            $this->handle_ping($client, $message);
            return;
        }
        if ($this->handle_error_message($client, $message) !== true) {
            return;
        }
        $topic = $this->safe_string($message, 'type');
        if ($topic !== null) {
            $methods = array(
                'ticker' => array($this, 'handle_ticker'),
                'orderbookdepth' => array($this, 'handle_order_book'),
                'orderbook' => array($this, 'handle_order_book'),
                'transaction' => array($this, 'handle_trades'),
                'trade' => array($this, 'handle_trades'),
                'myAsset' => array($this, 'handle_balance'),
                'myOrder' => array($this, 'handle_orders'),
            );
            $method = $this->safe_value($methods, $topic);
            if ($method !== null) {
                $method($client, $message);
            }
        }
    }
}
